package com.dreamcore.workspace.departure;
import com.dreamcore.workspace.identity.*;import com.dreamcore.workspace.retention.RetentionClock;import com.dreamcore.workspace.retention.RetentionService;import java.io.*;import java.security.*;import java.time.*;import java.util.*;import java.util.function.Consumer;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.json.JsonMapper;
/** Frozen, actor-scoped inventory followed by bounded physical ZIP parts. No all-tenant private-content export. */
@Service public class DepartureArchiveService {
 public static final long TARGET_BYTES=33554432,MAX_ARCHIVE=41943040;public static final int MAX_ITEMS=50;
 public record Inventory(UUID id,UUID executionId,UUID workspaceId,boolean includeHistory,String state,int revision,long itemCount,long pending,long included,long failed,boolean selectedScopeComplete,boolean fullTenantMigration,Instant createdAt,List<String> coverage){}
 public record Item(long ordinal,String kind,UUID objectId,UUID versionId,int version,String state,String filename,String sha256,String errorCode){}
 public record Part(UUID id,UUID setId,int number,String state,int revision,int requestedCount,long bytes,String sha256,Instant generatedAt,Instant expiresAt,String errorCode,String cleanupState,Instant cleanedAt,long removedBytes,boolean canDownload,List<Item> items){}
 public record Page<T>(List<T> items,boolean hasMore){}
 public record Job(UUID partId,UUID setId,UUID tenant,UUID actor,UUID execution,UUID workspace,UUID token,List<Long> ordinals){}
 public record Stamp(Instant generatedAt,Instant expiresAt){}
 public record DownloadInfo(String filename,long bytes,String sha256){}
 private final JdbcTemplate db;private final IdentityService identities;private final IdentityAudit audit;private final DepartureArchiveSources sources;private final DepartureAccess gate;private final RetentionService retention;private final RetentionClock clock;private final JsonMapper json=new JsonMapper();
 public DepartureArchiveService(JdbcTemplate db,IdentityService identities,IdentityAudit audit,DepartureArchiveSources sources,DepartureAccess gate,RetentionService retention,RetentionClock clock){this.db=db;this.identities=identities;this.audit=audit;this.sources=sources;this.gate=gate;this.retention=retention;this.clock=clock;}
 private Instant time(Map<String,Object>r,String k){return r.get(k)==null?null:((java.sql.Timestamp)r.get(k)).toInstant();}
 private void page(int offset,int limit){if(offset<0||offset>100000||limit<1||limit>50)throw IdentityException.invalid();}
 private Map<String,Object> set(UUID actor,UUID tenant,UUID id,boolean lock){identities.member(actor,tenant,false);var rows=db.queryForList("SELECT * FROM departure_export_sets WHERE id=? AND tenant_id=? AND owner_id=?"+(lock?" FOR UPDATE":""),id,tenant,actor);if(rows.isEmpty())throw new IdentityException(404,"DEPARTURE_EXPORT_NOT_FOUND");var s=rows.getFirst();sources.scope(actor,tenant,(UUID)s.get("execution_id"),(UUID)s.get("workspace_id"));return s;}
 private Map<String,Object> partRow(UUID actor,UUID tenant,UUID id,boolean lock){var rows=db.queryForList("SELECT p.*,s.tenant_id,s.owner_id,s.execution_id,s.workspace_id FROM departure_export_parts p JOIN departure_export_sets s ON s.id=p.set_id WHERE p.id=? AND s.tenant_id=? AND s.owner_id=?"+(lock?" FOR UPDATE OF p":""),id,tenant,actor);if(rows.isEmpty())throw new IdentityException(404,"DEPARTURE_EXPORT_NOT_FOUND");var p=rows.getFirst();sources.scope(actor,tenant,(UUID)p.get("execution_id"),(UUID)p.get("workspace_id"));return p;}
 private DepartureArchiveSources.Item selection(Map<String,Object>r){return new DepartureArchiveSources.Item((String)r.get("kind"),(UUID)r.get("object_id"),(UUID)r.get("version_id"),(Integer)r.get("version"));}
 @Transactional public Inventory create(UUID actor,UUID tenant,UUID execution,UUID workspace,UUID key,boolean history){String fp=IdentityService.hash(json.writeValueAsString(new Object[]{tenant,execution,workspace,history}));UUID prior=identities.priorRequest(actor,key,"DEPARTURE_EXPORT_INVENTORY",fp);sources.scope(actor,tenant,execution,workspace);if(prior!=null)return get(actor,tenant,prior);UUID id=UUID.randomUUID();db.update("INSERT INTO departure_export_sets(id,execution_id,tenant_id,owner_id,workspace_id,include_history,item_count,created_at) VALUES (?,?,?,?,?,?,0,?)",id,execution,tenant,actor,workspace,history,java.sql.Timestamp.from(clock.now()));
  db.update("""
   INSERT INTO departure_export_items(set_id,ordinal,kind,object_id,version_id,version,size_bytes)
   SELECT ?,row_number() OVER(ORDER BY kind,object_id,version),kind,object_id,version_id,version,size_bytes FROM (
    SELECT 'MATERIAL_VERSION' AS kind,m.id AS object_id,v.id AS version_id,v.number AS version,v.size_bytes FROM active_materials m JOIN material_versions v ON v.material_id=m.id
     WHERE m.tenant_id=? AND m.workspace_id=? AND (? OR v.number=m.current_version)
    UNION ALL SELECT 'EXPERIENCE_VERSION',e.id,v.id,v.number,131072 FROM experience_entries e JOIN experience_versions v ON v.entry_id=e.id
     WHERE e.tenant_id=? AND e.workspace_id=? AND v.access_mode='INDEPENDENT_COPY' AND NOT v.scrubbed AND
      ((NOT ? AND e.status='PUBLISHED' AND e.published_version=v.id) OR (? AND EXISTS(SELECT 1 FROM experience_events x WHERE x.entry_id=e.id AND x.version_id=v.id AND x.action='PUBLISHED')))
    UNION ALL SELECT 'DATASET_SNAPSHOT',d.id,s.id,s.version,octet_length(s.data_rows::text)::bigint+131072 FROM business_datasets d JOIN dataset_snapshots s ON s.dataset_id=d.id
     WHERE d.tenant_id=? AND d.workspace_id=? AND d.status='ACTIVE' AND NOT d.scrubbed AND NOT s.scrubbed AND (? OR s.id=d.current_snapshot)
   ) inventory
   """,id,tenant,workspace,history,tenant,workspace,history,history,tenant,workspace,history);db.update("UPDATE departure_export_sets SET item_count=(SELECT count(*) FROM departure_export_items WHERE set_id=?) WHERE id=?",id,id);identities.remember(actor,key,"DEPARTURE_EXPORT_INVENTORY",fp,id);audit.record(actor,tenant,"EXIT_EXPORT_INVENTORY",id,"SUCCESS");return get(actor,tenant,id);
 }
 @Transactional public Inventory get(UUID actor,UUID tenant,UUID id){var s=set(actor,tenant,id,false);var n=db.queryForMap("SELECT count(*) FILTER(WHERE state='PENDING') pending,count(*) FILTER(WHERE state='INCLUDED') included,count(*) FILTER(WHERE state='FAILED') failed FROM departure_export_items WHERE set_id=?",id);long total=(Long)s.get("item_count"),pending=(Long)n.get("pending"),failed=(Long)n.get("failed");return new Inventory(id,(UUID)s.get("execution_id"),(UUID)s.get("workspace_id"),(Boolean)s.get("include_history"),(String)s.get("state"),(Integer)s.get("revision"),total,pending,(Long)n.get("included"),failed,total>0&&pending==0&&failed==0,false,time(s,"created_at"),List.of("只包含本次指定、当前获权共享空间的原资料、已采集数据快照及显式发布的独立经验","原资料以原始格式提供，独立企业发布成果已包含在目标原资料中；每个条目固定版本","经验包含独立正文、版本、手工整理与未评测标记；不复制原会话或受限来源正文","数据快照按固定版本输出 JSON，含批准列、数据行及真实覆盖时间；外部系统全库不包含","私人空间、私人会话/文稿/反馈、凭据、权限配置及平台诊断不包含","回收中或已清理资料不包含；历史版本只在本次明确勾选时纳入","每个分包最多50项/32MiB计划内容；过大原件会报告缺项，不以空包宣称成功","所选范围生成完整不代表全企业迁出或已交接验收；每次下载重新核对当前授权"));}
 @Transactional public Page<Inventory> list(UUID actor,UUID tenant,UUID execution,int offset,int limit){identities.member(actor,tenant,false);page(offset,limit);var ids=db.queryForList("SELECT id FROM departure_export_sets WHERE tenant_id=? AND owner_id=? AND execution_id=? ORDER BY created_at DESC,id LIMIT ? OFFSET ?",UUID.class,tenant,actor,execution,limit+1,offset);List<Inventory> result=new ArrayList<>();for(UUID id:ids.stream().limit(limit).toList())result.add(get(actor,tenant,id));return new Page<>(result,ids.size()>limit);}
 @Transactional public Page<Part> parts(UUID actor,UUID tenant,UUID setId,int offset,int limit){set(actor,tenant,setId,false);page(offset,limit);var ids=db.queryForList("SELECT id FROM departure_export_parts WHERE set_id=? ORDER BY number DESC LIMIT ? OFFSET ?",UUID.class,setId,limit+1,offset);return new Page<>(ids.stream().limit(limit).map(id->part(actor,tenant,id)).toList(),ids.size()>limit);}
 @Transactional public Part next(UUID actor,UUID tenant,UUID setId,UUID key){String fp=IdentityService.hash(tenant+"\n"+setId);UUID prior=identities.priorRequest(actor,key,"DEPARTURE_EXPORT_PART",fp);var s=set(actor,tenant,setId,true);if(prior!=null)return part(actor,tenant,prior);var rows=db.queryForList("SELECT ordinal,size_bytes FROM departure_export_items WHERE set_id=? AND part_id IS NULL ORDER BY ordinal LIMIT 50",setId);if(rows.isEmpty())throw new IdentityException(409,"DEPARTURE_NO_PENDING_ITEMS");List<Long> ordinals=new ArrayList<>();long bytes=0;for(var r:rows){long size=(Long)r.get("size_bytes");if(!ordinals.isEmpty()&&bytes+size>TARGET_BYTES)break;ordinals.add((Long)r.get("ordinal"));bytes+=size;if(bytes>=TARGET_BYTES)break;}UUID id=UUID.randomUUID();int number=db.queryForObject("SELECT coalesce(max(number),0)+1 FROM departure_export_parts WHERE set_id=?",Integer.class,setId);db.update("INSERT INTO departure_export_parts(id,set_id,number,state,request_count,created_at) VALUES (?,?,?,'QUEUED',?,?)",id,setId,number,ordinals.size(),java.sql.Timestamp.from(clock.now()));for(long ordinal:ordinals)db.update("UPDATE departure_export_items SET part_id=? WHERE set_id=? AND ordinal=? AND part_id IS NULL",id,setId,ordinal);db.update("UPDATE departure_export_sets SET revision=revision+1 WHERE id=?",setId);identities.remember(actor,key,"DEPARTURE_EXPORT_PART",fp,id);audit.record(actor,tenant,"EXIT_EXPORT_PART",id,"SUCCESS");return part(actor,tenant,id);}
 private List<Map<String,Object>> rows(UUID part){return db.queryForList("SELECT * FROM departure_export_items WHERE part_id=? ORDER BY ordinal",part);}
 private boolean usable(Map<String,Object>p){return Set.of("READY","PARTIAL").contains(p.get("state"))&&p.get("expires_at")!=null&&clock.now().isBefore(time(p,"expires_at"))&&p.get("cleanup_state").equals("NONE");}
 @Transactional public Part part(UUID actor,UUID tenant,UUID id){var p=partRow(actor,tenant,id,false);List<Item> items=new ArrayList<>();boolean all=true;int success=0;for(var r:rows(id)){boolean visible=true;try{sources.inspect(actor,tenant,(UUID)p.get("execution_id"),(UUID)p.get("workspace_id"),selection(r));}catch(IdentityException ex){if(ex.status>=500)throw ex;visible=false;if(r.get("state").equals("INCLUDED"))all=false;}if(r.get("state").equals("INCLUDED"))success++;items.add(new Item((Long)r.get("ordinal"),(String)r.get("kind"),(UUID)r.get("object_id"),(UUID)r.get("version_id"),(Integer)r.get("version"),(String)r.get("state"),visible?(String)r.get("filename"):null,visible?(String)r.get("sha256"):null,visible?(String)r.get("error_code"):"DEPARTURE_EXPORT_ITEM_UNAVAILABLE"));}return new Part(id,(UUID)p.get("set_id"),(Integer)p.get("number"),(String)p.get("state"),(Integer)p.get("revision"),(Integer)p.get("request_count"),(Long)p.get("bytes"),(String)p.get("sha256"),time(p,"generated_at"),time(p,"expires_at"),(String)p.get("error_code"),(String)p.get("cleanup_state"),time(p,"cleaned_at"),(Long)p.get("removed_bytes"),usable(p)&&all&&success>0,items);}
 @Transactional public Job claim(){var rows=db.queryForList("SELECT p.*,s.tenant_id,s.owner_id,s.execution_id,s.workspace_id FROM departure_export_parts p JOIN departure_export_sets s ON s.id=p.set_id WHERE p.state='QUEUED' OR(p.state='GENERATING' AND p.lease_until<now()) ORDER BY p.created_at,p.id FOR UPDATE OF p SKIP LOCKED LIMIT 1");if(rows.isEmpty())return null;var r=rows.getFirst();UUID id=(UUID)r.get("id"),token=UUID.randomUUID();db.update("DELETE FROM departure_archive_chunks WHERE part_id=?",id);db.update("UPDATE departure_export_items SET state='PENDING',filename=NULL,sha256=NULL,error_code=NULL WHERE part_id=?",id);db.update("UPDATE departure_export_parts SET state='GENERATING',revision=revision+1,lease_token=?,generation=?,lease_until=now()+interval '10 minutes',error_code=NULL,bytes=0,sha256=NULL WHERE id=?",token,token,id);return new Job(id,(UUID)r.get("set_id"),(UUID)r.get("tenant_id"),(UUID)r.get("owner_id"),(UUID)r.get("execution_id"),(UUID)r.get("workspace_id"),token,this.rows(id).stream().map(i->(Long)i.get("ordinal")).toList());}
 private void owned(Job j){if(db.queryForList("SELECT id FROM departure_export_parts WHERE id=? AND lease_token=? AND state='GENERATING' AND lease_until>now() FOR UPDATE",j.partId(),j.token()).isEmpty())throw new IdentityException(409,"DEPARTURE_EXPORT_LEASE_LOST");}
 @Transactional public DepartureArchiveSources.Item selection(Job j,long ordinal){owned(j);return selection(db.queryForMap("SELECT * FROM departure_export_items WHERE set_id=? AND part_id=? AND ordinal=?",j.setId(),j.partId(),ordinal));}
 @Transactional public void item(Job j,long ordinal,String name,String hash,String error){owned(j);db.update("UPDATE departure_export_items SET state=?,filename=?,sha256=?,error_code=? WHERE part_id=? AND ordinal=?",error==null?"INCLUDED":"FAILED",name,hash,error,j.partId(),ordinal);}
 @Transactional public void chunk(Job j,int ordinal,byte[] bytes){owned(j);if(ordinal<0||ordinal>=640||bytes.length<1||bytes.length>65536)throw new IdentityException(413,"DEPARTURE_EXPORT_ARCHIVE_LIMIT");db.update("INSERT INTO departure_archive_chunks(part_id,generation,ordinal,content) VALUES (?,?,?,?)",j.partId(),j.token(),ordinal,bytes);}
 @Transactional public Stamp stamp(Job j){owned(j);Instant now=clock.now(),deadline=retention.resolveDeadline(j.tenant(),"EXPORT_PACKAGE",now).dueAt();deadline=deadline.isAfter(now.plus(Duration.ofDays(7)))?now.plus(Duration.ofDays(7)):deadline;return new Stamp(now,gate.capPackageExpiry(j.actor(),j.tenant(),j.workspace(),deadline));}
 @Transactional public List<Item> manifest(Job j){owned(j);return rows(j.partId()).stream().map(r->new Item((Long)r.get("ordinal"),(String)r.get("kind"),(UUID)r.get("object_id"),(UUID)r.get("version_id"),(Integer)r.get("version"),(String)r.get("state"),(String)r.get("filename"),(String)r.get("sha256"),(String)r.get("error_code"))).toList();}
 @Transactional public void finish(Job j,Stamp stamp,long bytes,String hash){sources.scope(j.actor(),j.tenant(),j.execution(),j.workspace());owned(j);int included=0,failed=0;for(var r:rows(j.partId()))if(r.get("state").equals("INCLUDED")){included++;sources.inspect(j.actor(),j.tenant(),j.execution(),j.workspace(),selection(r));}else failed++;if(included==0)throw new IdentityException(409,"DEPARTURE_EXPORT_NO_CONTENT");if(bytes<1||bytes>MAX_ARCHIVE)throw new IdentityException(413,"DEPARTURE_EXPORT_ARCHIVE_LIMIT");db.update("UPDATE departure_export_parts SET state=?,revision=revision+1,bytes=?,sha256=?,generated_at=coalesce(generated_at,?),expires_at=least(coalesce(expires_at,?),?),lease_token=NULL,lease_until=NULL WHERE id=?",failed>0?"PARTIAL":"READY",bytes,hash,java.sql.Timestamp.from(stamp.generatedAt()),java.sql.Timestamp.from(stamp.expiresAt()),java.sql.Timestamp.from(stamp.expiresAt()),j.partId());}
 @Transactional public void fail(Job j,String code){if(db.queryForList("SELECT id FROM departure_export_parts WHERE id=? AND lease_token=? AND state='GENERATING' FOR UPDATE",j.partId(),j.token()).isEmpty())return;db.update("DELETE FROM departure_archive_chunks WHERE part_id=?",j.partId());db.update("UPDATE departure_export_parts SET state='FAILED',revision=revision+1,error_code=?,lease_token=NULL,lease_until=NULL,bytes=0,sha256=NULL WHERE id=?",code,j.partId());db.update("UPDATE departure_export_items SET state='FAILED',filename=NULL,sha256=NULL,error_code=coalesce(error_code,?) WHERE part_id=?",code,j.partId());}
 @Transactional public Part command(UUID actor,UUID tenant,UUID id,UUID key,int expected,String action){if(expected<1||!Set.of("RETRY","REMOVE").contains(action==null?"":action))throw IdentityException.invalid();String fp=IdentityService.hash(json.writeValueAsString(new Object[]{tenant,id,expected,action}));UUID prior=identities.priorRequest(actor,key,"EXIT_EXPORT_COMMAND",fp);var p=partRow(actor,tenant,id,true);if(prior!=null)return part(actor,tenant,prior);if((Integer)p.get("revision")!=expected)throw new IdentityException(409,"DEPARTURE_REVISION_CONFLICT");if(action.equals("RETRY")){if(!Set.of("FAILED","PARTIAL").contains(p.get("state"))||!p.get("cleanup_state").equals("NONE")||(p.get("expires_at")!=null&&!clock.now().isBefore(time(p,"expires_at"))))throw new IdentityException(409,"DEPARTURE_EXPORT_STATE_CONFLICT");db.update("DELETE FROM departure_archive_chunks WHERE part_id=?",id);db.update("UPDATE departure_export_parts SET state='QUEUED',revision=revision+1,bytes=0,sha256=NULL,error_code=NULL WHERE id=?",id);}else{if(Set.of("REMOVED","EXPIRED","REVOKED").contains(p.get("state")))throw new IdentityException(409,"DEPARTURE_EXPORT_STATE_CONFLICT");db.update("UPDATE departure_export_parts SET state='REMOVED',revision=revision+1,cleanup_state='PENDING',lease_token=NULL,lease_until=NULL WHERE id=?",id);}identities.remember(actor,key,"EXIT_EXPORT_COMMAND",fp,id);audit.record(actor,tenant,"EXIT_EXPORT_"+action,id,"SUCCESS");return part(actor,tenant,id);}
 @Transactional public int expireDue(){return db.update("UPDATE departure_export_parts p SET state='EXPIRED',revision=p.revision+1,lease_token=NULL,lease_until=NULL,cleanup_state='PENDING' FROM departure_export_sets s JOIN departure_executions e ON e.id=s.execution_id WHERE p.set_id=s.id AND p.cleanup_state='NONE' AND (e.deadline<=clock_timestamp() OR e.state<>'EXPORT_WINDOW' OR p.expires_at<=clock_timestamp() OR (p.expires_at IS NULL AND p.created_at<clock_timestamp()-interval '1 day'))");}
 public List<UUID> pendingCleanup(){return db.queryForList("SELECT id FROM departure_export_parts WHERE cleanup_state IN('PENDING','FAILED') ORDER BY created_at,id LIMIT 10",UUID.class);}
 @Transactional public void cleanup(UUID id){if(db.queryForList("SELECT id FROM departure_export_parts WHERE id=? AND cleanup_state IN('PENDING','FAILED') FOR UPDATE",id).isEmpty())return;long bytes=db.queryForObject("SELECT coalesce(sum(octet_length(content)),0) FROM departure_archive_chunks WHERE part_id=?",Long.class,id);db.update("DELETE FROM departure_archive_chunks WHERE part_id=?",id);db.update("UPDATE departure_export_items SET filename=NULL,sha256=NULL WHERE part_id=?",id);db.update("UPDATE departure_export_parts SET cleanup_state='COMPLETE',cleaned_at=now(),cleanup_attempts=cleanup_attempts+1,removed_bytes=removed_bytes+?,revision=revision+1 WHERE id=?",bytes,id);}
 @Transactional public void cleanupFailed(UUID id){db.update("UPDATE departure_export_parts SET cleanup_state='FAILED',cleanup_attempts=cleanup_attempts+1,error_code='DEPARTURE_EXPORT_CLEANUP_FAILED',revision=revision+1 WHERE id=? AND cleanup_state IN('PENDING','FAILED')",id);}
 /** Caller holds tenant/execution lock after the fixed formal deadline. Actual chunks must be gone before online completion. */
 @Transactional public boolean cleanupExecution(UUID execution){db.update("UPDATE departure_export_parts p SET state='EXPIRED',revision=p.revision+1,cleanup_state='PENDING',lease_token=NULL,lease_until=NULL FROM departure_export_sets s WHERE p.set_id=s.id AND s.execution_id=? AND p.cleanup_state='NONE'",execution);var ids=db.queryForList("SELECT p.id FROM departure_export_parts p JOIN departure_export_sets s ON s.id=p.set_id WHERE s.execution_id=? AND p.cleanup_state IN('PENDING','FAILED') ORDER BY p.id LIMIT 10",UUID.class,execution);for(UUID id:ids)cleanup(id);return !Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM departure_export_parts p JOIN departure_export_sets s ON s.id=p.set_id WHERE s.execution_id=? AND(p.cleanup_state<>'COMPLETE' OR EXISTS(SELECT 1 FROM departure_archive_chunks c WHERE c.part_id=p.id)))",Boolean.class,execution));}
 public record CleanupReceipt(UUID partId,String state,String cleanupState,int attempts,Instant completedAt,long removedBytes,String backupState){}
 @Transactional public CleanupReceipt receipt(UUID actor,UUID tenant,UUID id){identities.member(actor,tenant,false);var rows=db.query("SELECT p.* FROM departure_export_parts p JOIN departure_export_sets s ON s.id=p.set_id WHERE p.id=? AND s.tenant_id=? AND s.owner_id=?",(r,n)->new CleanupReceipt(id,r.getString("state"),r.getString("cleanup_state"),r.getInt("cleanup_attempts"),r.getTimestamp("cleaned_at")==null?null:r.getTimestamp("cleaned_at").toInstant(),r.getLong("removed_bytes"),"PENDING_VERIFICATION"),id,tenant,actor);if(rows.isEmpty())throw new IdentityException(404,"DEPARTURE_EXPORT_NOT_FOUND");return rows.getFirst();}
 @Transactional public Page<CleanupReceipt> receipts(UUID actor,UUID tenant,UUID execution,int offset,int limit){identities.member(actor,tenant,false);page(offset,limit);var ids=db.queryForList("SELECT p.id FROM departure_export_parts p JOIN departure_export_sets s ON s.id=p.set_id WHERE s.tenant_id=? AND s.owner_id=? AND s.execution_id=? ORDER BY p.created_at DESC,p.id LIMIT ? OFFSET ?",UUID.class,tenant,actor,execution,limit+1,offset);return new Page<>(ids.stream().limit(limit).map(id->receipt(actor,tenant,id)).toList(),ids.size()>limit);}
 private long chunks(UUID part,UUID generation,OutputStream out,MessageDigest digest)throws IOException{long[] bytes={0};int[] ordinal={0};IOException[] error={null};db.query(connection->{var s=connection.prepareStatement("SELECT ordinal,content FROM departure_archive_chunks WHERE part_id=? AND generation=? ORDER BY ordinal");s.setObject(1,part);s.setObject(2,generation);s.setFetchSize(1);return s;},rs->{while(rs.next()){if(rs.getInt(1)!=ordinal[0]++)throw new IdentityException(503,"DEPARTURE_EXPORT_ARCHIVE_INVALID");byte[] b=rs.getBytes(2);bytes[0]+=b.length;if(bytes[0]>MAX_ARCHIVE)throw new IdentityException(503,"DEPARTURE_EXPORT_ARCHIVE_INVALID");if(digest!=null)digest.update(b);if(out!=null)try{out.write(b);}catch(IOException e){error[0]=e;return null;}}return null;});if(error[0]!=null)throw error[0];return bytes[0];}
 @Transactional public void download(UUID actor,UUID tenant,UUID id,Consumer<DownloadInfo> begin,OutputStream out)throws IOException{identities.member(actor,tenant,false);var p=partRow(actor,tenant,id,true);if(!usable(p))throw new IdentityException(410,"DEPARTURE_EXPORT_NOT_DOWNLOADABLE");int included=0;for(var r:rows(id))if(r.get("state").equals("INCLUDED")){included++;sources.inspect(actor,tenant,(UUID)p.get("execution_id"),(UUID)p.get("workspace_id"),selection(r));}if(included==0)throw new IdentityException(410,"DEPARTURE_EXPORT_NO_CONTENT");MessageDigest digest;try{digest=MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}long bytes=chunks(id,(UUID)p.get("generation"),null,digest);String hash=HexFormat.of().formatHex(digest.digest());if(bytes!=(Long)p.get("bytes")||!hash.equals(p.get("sha256")))throw new IdentityException(503,"DEPARTURE_EXPORT_ARCHIVE_INVALID");begin.accept(new DownloadInfo("dreamcore-exit-part-"+p.get("number")+"-"+id+".zip",bytes,hash));chunks(id,(UUID)p.get("generation"),out,null);audit.record(actor,tenant,"EXIT_EXPORT_DOWNLOAD",id,"SUCCESS");}
}
